-- Baseline do histórico de migrações do Supabase (16/11/2026)
--
-- ⚠️ Rodar UMA vez, ANTES de ligar a integração GitHub do Supabase com "Deploy to production".
-- Marca como JÁ APLICADAS as 714 migrações que existiam até a 20261159 (todas foram
-- aplicadas à mão no SQL Editor, então o histórico do Supabase não as conhecia). Sem isto, a
-- integração tentaria rodar todas de novo no primeiro merge na main.
-- A 20261160 (recompra em tabela) NÃO entra: ainda não foi aplicada; é a primeira que a
-- integração vai aplicar sozinha.
--
-- Idempotente (on conflict do nothing). O resultado final mostra quantas linhas há no
-- histórico e se existe versão no histórico que NÃO é de um arquivo desta lista
-- (esperado: nenhuma — versão "só no histórico" faz a integração recusar o deploy).

create schema if not exists supabase_migrations;
create table if not exists supabase_migrations.schema_migrations (
  version    text not null primary key,
  statements text[],
  name       text
);

