insert into supabase_migrations.schema_migrations (version)
select version from _versoes_baseline
on conflict (version) do nothing;

select (select count(*) from supabase_migrations.schema_migrations)                          as linhas_no_historico,
       (select count(*) from _versoes_baseline)                                              as versoes_da_lista,
       (select count(*) from supabase_migrations.schema_migrations h
         where h.version in (select version from _versoes_baseline))                         as da_lista_no_historico,
       (select coalesce(string_agg(h.version, ', ' order by h.version), '(nenhuma)')
          from supabase_migrations.schema_migrations h
         where h.version not in (select version from _versoes_baseline))                     as so_no_historico;
